import {shuffle,isSolvedPuzzle,rand} from '../logic.js';import {gameFrame,roundFlow} from '../ui.js';
function picture(seed){const palettes=[['#172f52','#5895d6','#e2af63','#dbe8ec'],['#174d49','#56a798','#e7b380','#e2efe6'],['#453f75','#8f7ec1','#e5a48c','#eee9f7']];const p=palettes[seed%3];return `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300" viewBox="0 0 300 300"><rect width="300" height="300" fill="${p[3]}"/><rect x="20" y="20" width="130" height="260" fill="${p[0]}"/><circle cx="155" cy="100" r="77" fill="${p[2]}"/><path d="M20 280 172 130 280 280Z" fill="${p[1]}"/><rect x="220" y="25" width="55" height="55" fill="${p[1]}"/><circle cx="240" cy="215" r="30" fill="${p[0]}"/><path d="M25 145h120M25 165h100" stroke="${p[3]}" stroke-width="7"/></svg>`;}
export function mountGame(root,c){const flow=roundFlow(root,c),size=c.difficulty==='hard'?4:3;function next(){flow.next();const url=`url("data:image/svg+xml,${encodeURIComponent(picture(rand(30)))}")`;let tiles=shuffle(Array.from({length:size*size},(_,i)=>i));if(isSolvedPuzzle(tiles))[tiles[0],tiles[1]]=[tiles[1],tiles[0]];let selected=null;const area=gameFrame(root,'Study the image','Remember where the colors and shapes meet.');area.innerHTML=`<div class="puzzle-preview" style='background-image:${url}' role="img" aria-label="Geometric image to memorize"></div><p class="subtle">${c.mode==='learn'?'Take your time, then mix the pieces.':'The pieces will mix in a moment.'}</p>${c.mode==='learn'?'<button class="primary" id="mix">Mix the pieces</button>':''}`;function mix(){root.querySelector('.round-heading h2').textContent='Put the picture back together';root.querySelector('.round-heading p').textContent='Select two pieces to swap them. Every piece has one original position.';area.innerHTML=`<div class="tile-grid puzzle-board" style="--cols:${size}"></div><div class="choice-row"><button class="primary" id="check">Check picture</button>${c.mode==='learn'?'<button id="reveal">Show solution</button>':''}</div>`;const grid=area.querySelector('.tile-grid');function draw(){grid.innerHTML=tiles.map((piece,i)=>`<button class="puzzle-tile" data-i="${i}" aria-label="Piece at row ${Math.floor(i/size)+1}, column ${i%size+1}" aria-pressed="${selected===i}" style='background-image:${url};background-size:${size*100}%;background-position:${piece%size*100/(size-1)}% ${Math.floor(piece/size)*100/(size-1)}%'></button>`).join('');grid.querySelectorAll('button').forEach(b=>b.onclick=()=>{const i=+b.dataset.i;if(selected===null)selected=i;else{[tiles[selected],tiles[i]]=[tiles[i],tiles[selected]];selected=null;}draw();grid.querySelector(`[data-i="${i}"]`).focus();});}draw();area.querySelector('#check').onclick=()=>flow.answer(isSolvedPuzzle(tiles),'Trace the large circle and the diagonal edge to locate neighboring pieces.',next);area.querySelector('#reveal')?.addEventListener('click',()=>{flow.answer(false,'Solution shown. This round is recorded as assisted, not correct.',next);tiles=tiles.map((_,i)=>i);draw();grid.querySelectorAll('button').forEach(b=>b.disabled=true);});}if(c.mode==='learn')area.querySelector('#mix').onclick=mix;else c.session.schedule(mix,c.difficulty==='easy'?7000:c.difficulty==='hard'?3500:5000);}next();return {dispose(){}};}
